const rates = { vat: 20 };
const invoice = Object.create(rates);
const receipt = Object.create(rates);
const saved = { ...rates };

rates.vat = 22;
rates.tip = 10;

console.log(invoice.vat, receipt.tip);
console.log(saved.vat, saved.tip);

Object.setPrototypeOf(receipt, { vat: 5 });

console.log(receipt.vat, receipt.tip);
console.log(invoice.vat);
